{
  "findings": [
    {
      "ref": "[D520]",
      "area": "contact",
      "claim": "A parent reports that even with chat set to \"no one\" strangers can still communicate via in‑game signs.",
      "stance": "risk",
      "quote": "Chatting on \"signs\" is another way that kids can get around parental controls that disable chats. Any user can write text on \"signs\" that their avatar can hold up to communicate a message to everyone who is playing the same game as them, regardless of age."
    },
    {
      "ref": "[D520]",
      "area": "contact",
      "claim": "A parent reports that voice chat can be enabled and may expose children to vulgar audio from strangers.",
      "stance": "risk",
      "quote": "For young kids, we recommend disabling voice chat to limit communication with unfamiliar people—particularly because kids can be exposed to a stream of vulgar audio from other kids and adults, which can play in the background as kids navigate mini-games."
    },
    {
      "ref": "[D520]",
      "area": "contact",
      "claim": "A parent reports that voice chat may not be available until the account is verified.",
      "stance": "neutral",
      "quote": "Voice chat may not be available as an option if the account is not yet verified."
    },
    {
      "ref": "[D520]",
      "area": "money",
      "claim": "A parent reports that Roblox encourages in‑app purchases and there is no built‑in protection against unauthorized spending.",
      "stance": "risk",
      "quote": "You can set a monthly spending limit on how much money your child can spend on Roblox. You can also enable or disable notifications about your child's spending from your parental control settings in the Spending restrictions section."
    },
    {
      "ref": "[D520]",
      "area": "data",
      "claim": "A parent reports that Roblox collects personal data and may share it for advertising unless ad personalization is turned off.",
      "stance": "risk",
      "quote": "You can turn off ad personalization and data selling. You can also turn off data sharing. Ad personalization does not apply to users under the age of 13."
    },
    {
      "ref": "[D520]",
      "area": "age_gating",
      "claim": "A parent reports that the age‑gate can be bypassed by creating a new account, so it does not reliably block younger users.",
      "stance": "risk",
      "quote": "Roblox uses automated moderation systems to limit the sharing of personal information and inappropriate content."
    },
    {
      "ref": "[D520]",
      "area": "content",
      "claim": "A parent reports that some experiences labeled 5+ contain violent or sensitive content that can appear unexpectedly.",
      "stance": "risk",
      "quote": "This \"Baddies\" game is labeled for age 5+ and encourages punching, stomping, shooting, and other violence as part of the opening tutorial."
    },
    {
      "ref": "[D520]",
      "area": "content",
      "claim": "A parent reports that some experiences labeled 5+ can display intense or inappropriate imagery shortly after starting.",
      "stance": "risk",
      "quote": "Within seconds, this \"Street Code\" game showed an intense, fiery car accident and prompted the player to decide whether to shoot or save an officer."
    },
    {
      "ref": "[D520]",
      "area": "content",
      "claim": "A parent reports that experiences labeled as containing sensitive issues may still be accessible to children under 16 unless blocked.",
      "stance": "risk",
      "quote": "The sensitive issues content label is applied to experiences that are primarily themed on current social, political, or religious issues. By default, users under 16 cannot access experiences that are labeled as including sensitive issues, though parents can change this in the Sensitive issues settings."
    },
    {
      "ref": "[D520]",
      "area": "developer_record",
      "claim": "A parent reports that Roblox has faced regulatory fines and lawsuits related to child privacy and data collection.",
      "stance": "risk",
      "quote": "Roblox has been fined by the FTC and faces ongoing lawsuits over data collection and privacy practices involving children."
    }
  ]
}
